package com.xdownload.mobile;
import org.junit.*;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.util.zip.*;
public class FileToolsTest{
 @Test public void vaultRoundTripAndWrongPassword()throws Exception{File dir=Files.createTempDirectory("vaulttest").toFile();try{File src=new File(dir,"src"),enc=new File(dir,"enc"),dec=new File(dir,"dec");byte[] data=new byte[128000];new java.util.Random(123).nextBytes(data);Files.write(src.toPath(),data);FileTools.crypt(src,enc,"test-password".toCharArray(),true);FileTools.crypt(enc,dec,"test-password".toCharArray(),false);assertArrayEquals(data,Files.readAllBytes(dec.toPath()));try{FileTools.crypt(enc,dec,"wrong-password".toCharArray(),false);fail();}catch(Exception expected){assertFalse(dec.exists());}}finally{FileTools.deleteTree(dir);}}
 @Test public void zipExtractAndRejectTraversal()throws Exception{File dir=Files.createTempDirectory("ziptest").toFile();try{File zip=new File(dir,"a.zip"),out=new File(dir,"out");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(zip))){z.putNextEntry(new ZipEntry("folder/file.txt"));z.write(new byte[]{1,2,3});z.closeEntry();}assertEquals(1,FileTools.extractZip(zip,out));assertArrayEquals(new byte[]{1,2,3},Files.readAllBytes(new File(out,"folder/file.txt").toPath()));try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(zip))){z.putNextEntry(new ZipEntry("../escape"));z.write(1);z.closeEntry();}try{FileTools.extractZip(zip,new File(dir,"bad"));fail();}catch(IOException expected){assertFalse(new File(dir,"escape").exists());}}finally{FileTools.deleteTree(dir);}}
}